{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"authorship_tag":"ABX9TyMv7P2oKnyZ+hp3bN06zCUW"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","execution_count":10,"metadata":{"colab":{"base_uri":"https://localhost:8080/"},"id":"345Jbf3Z_kAy","executionInfo":{"status":"ok","timestamp":1794676941292,"user_tz":300,"elapsed":5,"user":{"displayName":"Sebastian Borja","userId":"02723758388444497235"}},"outputId":"d5a45931-d532-47a4-8df1-a6eb41d29b96"},"outputs":[{"output_type":"stream","name":"stdout","text":["ROOT_DIR detectado: /content/drive/MyDrive/agropulse_xai\n","\n","[FALTA] grid       -> /content/drive/MyDrive/agropulse_xai/data/parquet_VERIFICADO/harmonized_grid_30m.parquet\n","[OK] aligned    -> /content/drive/MyDrive/agropulse_xai/data/parquet_VERIFICADO/aligned_2016_2025.parquet\n","[OK] climate    -> /content/drive/MyDrive/agropulse_xai/data/parquet_VERIFICADO/climate_long_1981_2025.parquet\n","[OK] hls        -> /content/drive/MyDrive/agropulse_xai/data/parquet_VERIFICADO/hls_series_2016_2025.parquet\n","[OK] soil       -> /content/drive/MyDrive/agropulse_xai/data/parquet_VERIFICADO/D2_ssurgo_soil.parquet\n","[OK] catalog    -> /content/drive/MyDrive/agropulse_xai/catalog/crops_catalog.json\n"]}],"source":["from pathlib import Path\n","import sys\n","\n","# 1. Si corre en Google Colab y Drive no está montado, montarlo automáticamente\n","if Path(\"/content\").exists() and not Path(\"/content/drive/MyDrive\").exists():\n","    try:\n","        from google.colab import drive\n","        drive.mount(\"/content/drive\")\n","    except Exception as e:\n","        print(f\"Aviso al montar Drive: {e}\")\n","\n","# 2. Detectar ROOT_DIR (agropulse_xai/)\n","try:\n","    APP_DIR = Path(__file__).resolve().parent\n","    ROOT_DIR = Path(__file__).resolve().parents[2]\n","except NameError:\n","    colab_root = Path(\"/content/drive/MyDrive/agropulse_xai\")\n","    if colab_root.exists():\n","        ROOT_DIR = colab_root\n","    else:\n","        matches = list(Path(\"/content/drive/MyDrive\").glob(\"**/agropulse_xai\"))\n","        ROOT_DIR = matches[0] if matches else Path.cwd()\n","    APP_DIR = ROOT_DIR / \"RUTA_FINAL\" / \"2_APP\"\n","\n","# Carpetas oficiales de entrada\n","DATA_VERIFICADO_DIR = ROOT_DIR / \"data\" / \"parquet_VERIFICADO\"\n","METADATA_PATH = ROOT_DIR / \"data\" / \"metadata_run.json\"\n","CATALOG_PATH = ROOT_DIR / \"catalog\" / \"crops_catalog.json\"\n","\n","# Carpeta donde se integrarán los módulos reales del equipo\n","CORE_DIR = ROOT_DIR / \"core\"\n","if str(ROOT_DIR) not in sys.path:\n","    sys.path.insert(0, str(ROOT_DIR))\n","\n","# Caché local de la app\n","CACHE_DIR = APP_DIR / \"cache\"\n","CACHE_DIR.mkdir(parents=True, exist_ok=True)\n","\n","# Rutas exactas de los 5 Parquets limpios\n","FILES = {\n","    \"grid\": DATA_VERIFICADO_DIR / \"harmonized_grid_30m.parquet\",\n","    \"aligned\": DATA_VERIFICADO_DIR / \"aligned_2016_2025.parquet\",\n","    \"climate\": DATA_VERIFICADO_DIR / \"climate_long_1981_2025.parquet\",\n","    \"hls\": DATA_VERIFICADO_DIR / \"hls_series_2016_2025.parquet\",\n","    \"soil\": DATA_VERIFICADO_DIR / \"D2_ssurgo_soil.parquet\",\n","    \"catalog\": CATALOG_PATH,\n","}\n","\n","EXPECTED_PIXELS = 360\n","PARCEL_CENTER = {\"lat\": 42.083, \"lon\": -93.515}\n","\n","\n","def check_files() -> dict:\n","    \"\"\"Verifica que todos los insumos oficiales existan antes de levantar la app.\"\"\"\n","    return {\n","        key: {\"exists\": path.exists(), \"path\": str(path)}\n","        for key, path in FILES.items()\n","    }\n","\n","\n","if __name__ == \"__main__\":\n","    print(f\"ROOT_DIR detectado: {ROOT_DIR}\\n\")\n","    for k, info in check_files().items():\n","        mark = \"[OK]\" if info[\"exists\"] else \"[FALTA]\"\n","        print(f\"{mark} {k:10s} -> {info['path']}\")"]}]}